import os
import ast

file_list = []
function_list = []
class_list = []

for root, dirs, filenames in os.walk('.'):
    for filename in sorted(filenames):
        if filename.endswith('.py'):
            filepath = os.path.join(root, filename).lstrip('./')
            file_list.append(filepath)

