                        if isinstance(node, ast.ClassDef):
                            class_list.append(f"{filepath}:{node.name}")
                            for item in node.body:
                                if isinstance(item, ast.FunctionDef):
                                    function_list.append(f"{filepath}:{node.name}.{item.name}")
                        elif isinstance(node, ast.FunctionDef) and not any(isinstance(p, ast.ClassDef) for p in ast.walk(tree) if hasattr(p, 'body') and node in p.body):
                            function_list.append(f"{filepath}:{node.name}")
            except:
                pass

# Print results
print("FILES:", len(file_list))
for f in sorted(set(file_list)):
    print(f"  {f}")

print("\nCLASSES:", len(class_list))
for c in sorted(set(class_list)):
    print(f"  {c}")

print("\nFUNCTIONS:", len(function_list))
for fn in sorted(set(function_list)):
    print(f"  {fn}")
