import subprocess
import ast
import re

# Get all files from git
result = subprocess.run(['git', 'ls-tree', '-r', 'HEAD', '--name-only'], 
                       capture_output=True, text=True, cwd='/workspace')
all_files = [f for f in result.stdout.strip().split('\n') if f and f.endswith('.py')]

print("Python files found:")
for f in all_files:
    print(f"  {f}")

# Now analyze each file
file_contents = {}
for filepath in all_files:
    result = subprocess.run(['git', 'show', f'HEAD:{filepath}'], 
                           capture_output=True, text=True, cwd='/workspace')
    file_contents[filepath] = result.stdout

# Extract information
file_list = sorted(all_files)
function_list = []
class_list = []

for filepath, content in file_contents.items():
    try:
        tree = ast.parse(content)

        for node in tree.body:
            if isinstance(node, ast.ClassDef):
                class_list.append(f"{filepath}:{node.name}")
                for item in node.body:
                    if isinstance(item, ast.FunctionDef):
                        function_list.append(f"{filepath}:{node.name}.{item.name}")
            elif isinstance(node, ast.FunctionDef):
                function_list.append(f"{filepath}:{node.name}")
    except:
        pass

# Sort and deduplicate
function_list = sorted(set(function_list))
class_list = sorted(set(class_list))

# Search for currency-related code
print("\n\nCurrency-related code:")
for filepath, content in file_contents.items():
    for i, line in enumerate(content.split('\n'), 1):
        if re.search(r'currency|Currency|CURRENCY', line, re.IGNORECASE):
            print(f"{filepath}:{i}: {line.strip()}")

# Search for report-related code
print("\n\nReport-related code:")
for filepath, content in file_contents.items():
    for i, line in enumerate(content.split('\n'), 1):
        if re.search(r'report|Report|REPORT', line, re.IGNORECASE):
            print(f"{filepath}:{i}: {line.strip()}")

# Search for expense-related code
print("\n\nExpense-related code:")
for filepath, content in file_contents.items():
    for i, line in enumerate(content.split('\n'), 1):
        if re.search(r'expense|Expense|EXPENSE', line, re.IGNORECASE):
            print(f"{filepath}:{i}: {line.strip()}")

# Print summary
print(f"\n\nSummary:")
print(f"Files: {len(file_list)}")
print(f"Classes: {len(class_list)}")
print(f"Functions: {len(function_list)}")

# Print lists
print("\n\nFile list:")
for f in file_list:
    print(f"  {f}")

print("\n\nClass list:")
for c in class_list:
    print(f"  {c}")

print("\n\nFunction list:")
for fn in function_list:
    print(f"  {fn}")
